prototype_declarations.accache-production-preview-checks.nix:
let
  root = /home/dylan/src/aos/.worktrees/codex/bazel-integration-722;
  pkgs = (import root {}).pkgs;
  preview = import ./accache-production-preview.nix;
  checks = import (root + "/tests/build/_bazel-accache.nix") {
    pkgs = pkgs // {mkAosBazelPackage = _: preview.package;};
  };
  verifier = builtins.path {
    path = root + "/tools/bazel/tests";
    name = "aos-rust-family-parity-tools";
    filter = path: type: type == "regular" && builtins.elem (baseNameOf path) ["verify_protocol.py" "verify_pilot.py"];
  };
in rec {
  inherit (checks) installation;
  cargo = checks.cargo;
  integration = import (root + "/tests/build/accache.nix") {
    inherit pkgs;
    inherit (pkgs) lib;
    accache = preview.package;
    pname = "aos-bazel-accache-release-root-preview-integration";
  };
  tests = pkgs.mkAosBazelCheck {
    pname = "aos-bazel-accache-release-root-preview-tests";
    workspace = preview.workspace;
    retainActionGraph = true;
    targets = [
      "//crates/accache/accache:license_closure"
      "//crates/accache/accache:bin_accache"
      "//crates/accache/accache-frontend:license_closure"
      "//crates/accache/accache-frontend:unit"
      "//crates/accache/accache-frontend:doc"
    ];
  };
  parity = pkgs.runCommand "aos-bazel-accache-release-root-preview-cargo-parity" {
    buildDeps = [pkgs.python3];
  } ''
    mkdir -p "$out"
    ${pkgs.python3}/bin/python3 ${verifier}/verify_protocol.py \
      --tests ${tests}/evidence/tests --inventory ${tests}/inventory.json \
      --messages ${cargo}/cargo-messages.jsonl --cargo-log ${cargo}/cargo-tests.log \
      --package-path accache=crates/accache/accache \
      --package-path accache-frontend=crates/accache/accache-frontend \
      --output "$out/parity.json"
  '';
}

prototype_declarations.accache-production-preview.nix:
let
  root = /home/dylan/src/aos/.worktrees/codex/bazel-integration-722;
  pkgs = (import root {}).pkgs;
  unwinder = pkgs.mkAosBazelNativeLibraries {
    libraries.unwinder = {
      package = pkgs.gccUnwrapped // {targetSystem = pkgs.stdenv.hostPlatform.system;};
      headerPackage = pkgs.stdenv.glibc.dev // {targetSystem = pkgs.stdenv.hostPlatform.system;};
      libraryFile = "lib/gcc/${pkgs.stdenv.hostPlatform.config}/${pkgs.gccUnwrapped.version}/libgcc.a";
      linkage = "static";
    };
  };
  prefix = "//crates/accache/accache:";
  targets = map (name: prefix + name) ["accache" "package" "production_license_closure"];
  workspace = pkgs.mkAosBazelWorkspace {
    inherit root;
    sourceInventory = root + "/tools/bazel/metadata/accache-inventory.json";
    dependencyProfile = "accache";
    cargoProfile = "release";
    repositories = pkgs.aosBazelRepositories // pkgs.aosBazelRustRepositories.accache // {aos_native = unwinder;};
    rustcFlags = ["-Copt-level=3" "-Cdebuginfo=0" "-Cdebug-assertions=no" "-Coverflow-checks=no" "-Cstrip=symbols"];
    execRustcFlags = ["-Copt-level=0" "-Cdebuginfo=0" "-Cdebug-assertions=no" "-Coverflow-checks=no" "-Cstrip=symbols"];
    analysisTargets = targets;
  };
in rec {
  inherit workspace;
  build = pkgs.mkAosBazelBuild {
    pname = "aos-bazel-accache-production-release-root-preview";
    inherit workspace targets;
    retainActionGraph = true;
    sharedBuildCache = false;
  };
  package = pkgs.mkAosBazelPackage {
    pname = "accache";
    version = "0.1.0";
    inherit build;
    packageLabel = prefix + "package";
    meta = {
      description = "Daemonless compiler action cache for Nix build contracts";
      license = "Apache-2.0";
      mainProgram = "accache";
    };
  };
}
